from collections import Counter,defaultdict

def infer_pattern(grid):
    candidates=[]
    for period in range(2,13):
        buckets=defaultdict(Counter)
        for r in range(3,len(grid)):
            for c in range(3,len(grid[0])):
                v=grid[r][c]
                if v:
                    buckets[(r+c)%period][v]+=1
        score=sum(max(cnt.values()) for cnt in buckets.values())
        total=sum(sum(cnt.values()) for cnt in buckets.values())
        candidates.append((score/total, period, score,total, {k:cnt.most_common(1)[0][0] for k,cnt in buckets.items()}))
    return candidates
